            if (tk != "null") {
                Node* child = new Node(stoi(tk));
                child->parent = cur;
                if (side == 0) cur->left = child; else cur->right = child;
                if (child->val == x) target = child;
                q.push(child);
            }
        }
    }
    pair<int, int> r = neighbours(target);
