    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] toks = br.readLine().trim().split("\\s+");
        int x = Integer.parseInt(br.readLine().trim());
        Node root = new Node(Integer.parseInt(toks[0]));
        Node target = root.val == x ? root : null;
        ArrayDeque<Node> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < toks.length) {
            Node cur = queue.poll();
            for (int side = 0; side < 2 && i < toks.length; side++) {
                String t = toks[i++];
                if (!t.equals("null")) {
                    Node child = new Node(Integer.parseInt(t));
                    child.parent = cur;
                    if (side == 0) cur.left = child; else cur.right = child;
                    if (child.val == x) target = child;
                    queue.add(child);
                }
            }
        }
        int[] r = neighbours(target);
        System.out.println(r[0] + " " + r[1]);
    }
}
